<?= $this->section('scripts') ?><script>
$(function(){
 const form=$('#emailSettingsForm');
 function clearErrors(){form.find('.validation-error').empty();$('#testEmailForm .validation-error').empty();}
 form.on('submit',function(e){e.preventDefault();clearErrors();ajaxRequest({url:'<?= base_url('admin/configuration/settings/email-settings/save') ?>',data:form.serialize(),success:function(r){if(r.status){showSuccess(r.msg);setTimeout(function(){location.reload();},600);}else{showError(r.msg);if(r.errors)Object.keys(r.errors).forEach(function(k){$('[data-error-for="'+k+'"]').text(r.errors[k]);});}}});});
 $('#testEmailForm').on('submit',function(e){e.preventDefault();const test=$(this);ajaxRequest({url:'<?= base_url('admin/configuration/settings/email-settings/test') ?>',data:test.serialize(),success:function(r){if(r.status){showSuccess(r.msg);$('#testEmailModal').modal('hide');}else{showError(r.msg);if(r.errors)Object.keys(r.errors).forEach(function(k){test.find('[data-error-for="'+k+'"]').text(r.errors[k]);});}}});});
});
</script><?= $this->endSection() ?>
